package com.lianxibu.site.config;
import com.lianxibu.site.domain.jobs.SourceContractFacts;import com.lianxibu.site.domain.protocol.WireValues;import com.lianxibu.site.repository.jobs.*;import com.lianxibu.site.repository.sources.JdbcSourceContractFacts;import com.lianxibu.site.repository.settings.JdbcSettingsWrites;import com.lianxibu.site.service.jobs.*;import com.lianxibu.site.service.settings.SettingsJdbcStore;
import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;import java.util.concurrent.*;import javax.sql.DataSource;
import org.springframework.beans.factory.annotation.*;import org.springframework.boot.autoconfigure.condition.*;import org.springframework.context.SmartLifecycle;import org.springframework.context.annotation.*;import org.springframework.transaction.*;import org.springframework.transaction.support.*;
/** Explicit actual all-node source facts, private source binding and a separate sampler thread. */
@Configuration(proxyBeanMethods=false)
@ConditionalOnProperty(name={"site.ops.source-monitoring.enabled","site.browser.enabled","site.collector.enabled","site.sources.enabled"},havingValue="true")
public class SourceContractMonitoringConfiguration {
 public record Batch(List<SourceContractMonitoringCycle> cycles,SourceContractFacts.Api nativeFacts){public Batch{cycles=List.copyOf(cycles);if(cycles.isEmpty()||nativeFacts==null)throw new IllegalArgumentException("native source monitors required");}@Override public String toString(){return "SourceContractMonitoringBatch[redacted]";}}
 @Bean Batch sourceContractMonitoringBatch(DataSource source,PlatformTransactionManager tx,@Value("${SITE_OPERATIONAL_SCOPES}")String location){
  var scopes=OperationalScopeCatalog.load(location).scopes();if(scopes==null||scopes.sources().isEmpty())throw new IllegalStateException("native source operational bindings unavailable");var keys=new ArrayList<OperationalRuleEngine.Key>();
  for(var entry:new TreeMap<>(scopes.sources()).entrySet()){WireValues.id(entry.getKey(),true);var values=entry.getValue();if(values.size()!=1||!"OPS-07".equals(values.getFirst().ruleId())||!entry.getKey().equals(values.getFirst().resourceKey()))throw new IllegalStateException("native source operational bindings unavailable");keys.add(values.getFirst());}
  Clock clock=Clock.systemUTC();var facts=new JdbcSourceContractFacts(source,tx,clock);var settings=new SettingsJdbcStore(new JdbcSettingsWrites(source),ignored->false,change->{throw new IllegalStateException("read-only source monitoring settings");},clock);
  java.util.function.Supplier<OperationalMonitoringService.Configuration> current=()->{var config=settings.operationalConfiguration();return config.ready()?new OperationalMonitoringService.Configuration(config.revision(),config.rules()):null;};
  OperationalMonitoringService.ConfigurationSource configuration=()->{if(TransactionSynchronizationManager.isActualTransactionActive())return current.get();var reader=new TransactionTemplate(tx);reader.setReadOnly(true);reader.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);reader.setTimeout(10);return reader.execute(status->current.get());};
  var store=new OperationalJdbcStore(new JdbcOperationalSummaries(source),new JdbcJobRecords(source),clock);var monitor=new OperationalMonitoringService(store,configuration,new SharedWriteExecutor(new JdbcSharedWriteEntry(source),tx),clock);var cycles=new ArrayList<SourceContractMonitoringCycle>();for(var key:keys)cycles.add(new SourceContractMonitoringCycle(key,facts,store,monitor,clock));return new Batch(cycles,facts);
 }
 @Bean(destroyMethod="shutdownNow") @ConditionalOnMissingBean(name="sourceContractMonitoringExecutor") ScheduledExecutorService sourceContractMonitoringExecutor(){var executor=new ScheduledThreadPoolExecutor(1,task->{var thread=new Thread(task,"source-contract-monitor");thread.setDaemon(true);return thread;});executor.setRemoveOnCancelPolicy(true);executor.setExecuteExistingDelayedTasksAfterShutdownPolicy(false);executor.setContinueExistingPeriodicTasksAfterShutdownPolicy(false);return executor;}
 @Bean Loop sourceContractMonitoringLoop(Batch batch,@Qualifier("sourceContractMonitoringExecutor")ScheduledExecutorService executor){return new Loop(batch,executor,Clock.systemUTC());}
 public static final class Loop implements SmartLifecycle {
  private static final org.slf4j.Logger LOG=org.slf4j.LoggerFactory.getLogger(Loop.class);private final Batch batch;private final ScheduledExecutorService executor;private final Clock clock;private boolean running,inFlight;private volatile boolean failure;private ScheduledFuture<?> future;private final List<Runnable> callbacks=new ArrayList<>();
  Loop(Batch batch,ScheduledExecutorService executor,Clock clock){this.batch=Objects.requireNonNull(batch);this.executor=Objects.requireNonNull(executor);this.clock=Objects.requireNonNull(clock);}
  @Override public synchronized void start(){if(running)return;if(inFlight)throw new IllegalStateException("source sampling still stopping");batch.cycles().forEach(SourceContractMonitoringCycle::start);running=true;Instant now=clock.instant();long delay=Duration.between(now,now.truncatedTo(ChronoUnit.MINUTES).plusSeconds(60)).toNanos();try{future=Objects.requireNonNull(executor.scheduleAtFixedRate(this::tick,delay,TimeUnit.SECONDS.toNanos(60),TimeUnit.NANOSECONDS));}catch(RuntimeException rejected){running=false;batch.cycles().forEach(SourceContractMonitoringCycle::stop);future=null;throw rejected;}}
  private void tick(){synchronized(this){if(!running||inFlight)return;inFlight=true;}try{boolean failed=false;for(var cycle:batch.cycles()){synchronized(this){if(!running)break;}try{cycle.tick();}catch(RuntimeException unavailable){failed=true;}}if(failed&&!failure)LOG.warn("source_contract_monitoring_sample_failed");failure=failed;}finally{List<Runnable> done;synchronized(this){inFlight=false;done=List.copyOf(callbacks);callbacks.clear();}done.forEach(Runnable::run);}}
  @Override public void stop(){stop(null);}@Override public void stop(Runnable callback){boolean done;synchronized(this){running=false;batch.cycles().forEach(SourceContractMonitoringCycle::stop);if(future!=null){future.cancel(true);future=null;}done=!inFlight;if(!done&&callback!=null)callbacks.add(callback);}if(done&&callback!=null)callback.run();}
  @Override public synchronized boolean isRunning(){return running;}@Override public int getPhase(){return Integer.MAX_VALUE;}public boolean hasFailure(){return failure;}
 }
}
